nputDecoration(labelText:'Brand',border:OutlineInputBorder())))]),const SizedBox(height:10),TextField(controller:description,maxLines:3,decoration:const InputDecoration(labelText:'Description',border:OutlineInputBorder())),if(widget.type=='found'&&widget.cap['can_manage']==true)...[const SizedBox(height:10),TextField(controller:privateDetail,decoration:const InputDecoration(labelText:'Private ownership verification detail',helperText:'Hidden from students/parents',border:OutlineInputBorder()))],const SizedBox(height:12),OutlinedButton.icon(onPressed:pickGallery,icon:const Icon(Icons.photo_library),label:Text(imagePath==null?'Choose photo from Gallery':'Photo selected — change')),const SizedBox(height:16),SizedBox(width:double.infinity,child:FilledButton(onPressed:saving?null:save,child:Text(saving?'Saving...':'Save')))])) );}}
